import{_ as s,o as n,c as d,a2 as o}from"./chunks/framework.BetZR81g.js";const u=JSON.parse('{"title":"22 · 专题：笔记中所有通信协议汇总与比较","description":"","frontmatter":{},"headers":[],"relativePath":"embedded/GD32F407_myLibrary_note/22-专题-通信协议汇总与比较.md","filePath":"embedded/GD32F407_myLibrary_note/22-专题-通信协议汇总与比较.md","lastUpdated":1792564217000}'),r={name:"embedded/GD32F407_myLibrary_note/22-专题-通信协议汇总与比较.md"};function a(e,t,g,l,p,i){return n(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="_22-·-专题-笔记中所有通信协议汇总与比较" tabindex="-1">22 · 专题：笔记中所有通信协议汇总与比较 <a class="header-anchor" href="#_22-·-专题-笔记中所有通信协议汇总与比较" aria-label="Permalink to &quot;22 · 专题：笔记中所有通信协议汇总与比较&quot;">​</a></h1><blockquote><p><strong>这是一篇横向比较专题</strong>：把本工程用到的<strong>三种串行通信协议</strong>（USART / I2C / SPI）放在一张表上比，回答&quot;<strong>什么时候该用哪一个</strong>&quot;。 涉及模块：串口 USART（04、08）、IIC（15、17、18）、SPI（16、18）、以及硬件已有但代码未实现的 CAN / 单总线（20）。 整理日期：2026-10-06</p></blockquote><h2 id="怎么读这份笔记" tabindex="-1">怎么读这份笔记 <a class="header-anchor" href="#怎么读这份笔记" aria-label="Permalink to &quot;怎么读这份笔记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>建议路线</th></tr></thead><tbody><tr><td>「该用串口还是 I2C 还是 SPI？」</td><td><strong>第五章（选型决策）</strong> —— 直奔结论</td></tr><tr><td>想看一张总表</td><td>第三章（十一维度总表）+ 第四章（本工程实际用法）</td></tr><tr><td>想知道谁快</td><td>第六章（同为 1 KB 的耗时对比）——<strong>数字最直观</strong></td></tr><tr><td>想理解&quot;为什么 I2C 必须开漏&quot;</td><td>第七章（电气差异）</td></tr><tr><td>想补协议</td><td>第八章（本工程还没碰的 CAN / 单总线 / USB）</td></tr></tbody></table><h2 id="知识点地图" tabindex="-1">知识点地图 <a class="header-anchor" href="#知识点地图" aria-label="Permalink to &quot;知识点地图&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>串行通信协议汇总</span></span>
<span class="line"><span>├── 三个层次的差异   物理层（电气）→ 链路层（帧/应答）→ 应用层（寄存器/命令）</span></span>
<span class="line"><span>├── 三种协议          USART（异步）、I2C（同步、两线、有应答）、SPI（同步、四线、全双工）</span></span>
<span class="line"><span>├── 十一维度总表      线数/拓扑/寻址/同步/双工/时钟/速率/电气/应答/距离/引脚成本</span></span>
<span class="line"><span>├── 本工程实际用法     引脚、时钟、配置、速率、代码位置、应用场景</span></span>
<span class="line"><span>├── 耗时对比          同样传 1 KB：UART 88.9 ms / I2C 38 or 24 ms / SPI 0.40 ms</span></span>
<span class="line"><span>├── 电气差异          推挽 vs 开漏+上拉 → 决定了速率上限和&quot;多设备共线&quot;能力</span></span>
<span class="line"><span>├── 选型决策          从&quot;设备数量、距离、速率、是否需要应答&quot;四个问题出发</span></span>
<span class="line"><span>└── 未用到的协议      CAN（板上有 TJA1050）、单总线（DHT11）、USB、以太网</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>用&quot;线数 / 拓扑 / 寻址 / 同步 / 双工 / 速率 / 电气 / 应答&quot;八个词说清三种协议的差别</li><li>能在 30 秒内为一个新传感器/新器件选出正确的总线</li><li>记住 4 个具体数字：115200 波特率下一字节 86.8 μs、I2C 400 kHz 传 1 KB 约 24 ms、SPI 21 MHz 约 0.4 ms</li><li>理解&quot;开漏 vs 推挽&quot;为什么是 I2C 与 SPI 速率差距的根因</li><li>知道本工程还有哪些通信外设没用（CAN 等），以及什么时候会需要它们</li></ul><hr><h2 id="一、先分清-协议的三个层次" tabindex="-1">一、先分清&quot;协议的三个层次&quot; <a class="header-anchor" href="#一、先分清-协议的三个层次" aria-label="Permalink to &quot;一、先分清&quot;协议的三个层次&quot;&quot;">​</a></h2><p>通信协议不是一团东西，<strong>可以拆成三层看</strong>——分清了，比较才有依据：</p><table tabindex="0"><thead><tr><th>层次</th><th>关心什么</th><th>USART</th><th>I2C</th><th>SPI</th></tr></thead><tbody><tr><td><strong>物理层（电气）</strong></td><td>用几根线、什么电平、推挽还是开漏</td><td>2 线，推挽</td><td><strong>2 线，开漏 + 上拉</strong></td><td>4 线，推挽</td></tr><tr><td><strong>链路层（帧/时序）</strong></td><td>怎么分帧、怎么同步、有没有应答</td><td>起始位+数据位+停止位、<strong>无应答</strong></td><td>起始/地址/数据/<strong>ACK</strong>/停止</td><td>CS 选中 + 时钟移入移出、<strong>无应答</strong></td></tr><tr><td><strong>应用层（语义）</strong></td><td>字节代表什么</td><td>自定义（本工程是 printf 和命令）</td><td><strong>寄存器地址 + 数据</strong></td><td><strong>命令/地址 + 数据</strong></td></tr></tbody></table><p><strong>&quot;应用层&quot;这一层最容易被忽视，却最能决定代码形态</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I2C 器件（PCF8563）：写&quot;寄存器地址&quot;→ 再读写数据      → 接口长得像&quot;读写寄存器&quot;</span></span>
<span class="line"><span>SPI 器件（OLED/Flash）：拉低 CS → 发命令 → 发数据      → 接口长得像&quot;发命令流&quot;</span></span>
<span class="line"><span>UART：            没有约定，全靠你自己定协议          → 接口长得像&quot;收发字节&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p><strong>这解释了为什么三个驱动的 API 长得完全不同</strong>： <code>msp_iic_write_nbyte(addr, reg, data, len)</code> / <code>bsp_spi_oled_write_byte(dat, cmd)</code> / <code>send_string(huart, str)</code> —— <strong>API 的形态是被协议语义&quot;逼&quot;出来的，不是随便设计的</strong>（第 17/18 篇都印证了这一点）。</p></blockquote><hr><h2 id="二、三种协议各是什么-一句话版" tabindex="-1">二、三种协议各是什么（一句话版） <a class="header-anchor" href="#二、三种协议各是什么-一句话版" aria-label="Permalink to &quot;二、三种协议各是什么（一句话版）&quot;">​</a></h2><blockquote><p><strong>先补一个&quot;第四种&quot;</strong>：<strong>单总线（1-Wire / WS2812）</strong>——<strong>只有一根数据线，没有时钟线</strong>， 靠&quot;<strong>高电平持续多久</strong>&quot;或&quot;<strong>固定时隙</strong>&quot;来编码。第 30 篇的 WS2812 就是这一类： 它甚至可以用 <strong>SPI 的 MOSI 去&quot;发&quot;</strong>（把若干个 SPI 位拼成 1 个单总线位）， 见 <strong><a href="./30-WS2812彩灯.html">第 30 篇</a></strong>。<strong>&quot;用 SPI 发别的协议&quot;是嵌入式里很常见的一招。</strong></p></blockquote><table tabindex="0"><thead><tr><th>协议</th><th>一句话</th><th>本工程的典型场景</th></tr></thead><tbody><tr><td><strong>USART / UART</strong></td><td><strong>两个人打电报</strong>：约定好速度，一根线发一根线收，没有时钟线</td><td><code>printf</code> 调试输出；与 STC 单片机通信</td></tr><tr><td><strong>I2C</strong></td><td><strong>一条街上喊名字</strong>：两根线（时钟+数据），每个设备有地址，喊到谁谁应答</td><td>PCF8563（RTC）、OLED、触摸屏</td></tr><tr><td><strong>SPI</strong></td><td><strong>一条专线直达</strong>：四根线（时钟+双向数据+片选），选中谁就只跟谁说话</td><td>OLED（SPI 版）、字库芯片、SPI Flash</td></tr></tbody></table><hr><h2 id="三、【核心】十一维度总表" tabindex="-1">三、【核心】十一维度总表 <a class="header-anchor" href="#三、【核心】十一维度总表" aria-label="Permalink to &quot;三、【核心】十一维度总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>维度</th><th><strong>USART / UART</strong></th><th><strong>I2C</strong></th><th><strong>SPI</strong></th></tr></thead><tbody><tr><td>1</td><td><strong>线数</strong></td><td><strong>2</strong>（TX/RX）+ GND</td><td><strong>2</strong>（SCL/SDA）+ GND</td><td><strong>4</strong>（SCK/MOSI/MISO/CS）+ GND</td></tr><tr><td>2</td><td><strong>拓扑</strong></td><td>点对点（或两两互连）</td><td><strong>总线式，多设备并联</strong></td><td><strong>点对点</strong>（多设备各占一根 CS）</td></tr><tr><td>3</td><td><strong>寻址方式</strong></td><td>无（谁接谁就是谁）</td><td><strong>7 位地址</strong>（<code>addr &lt;&lt; 1 | rw</code>）</td><td><strong>CS 片选</strong>（无地址）</td></tr><tr><td>4</td><td><strong>同步 / 异步</strong></td><td><strong>异步</strong>（无时钟线，靠约定波特率）</td><td>同步（SCL 由主机产生）</td><td>同步（SCK 由主机产生）</td></tr><tr><td>5</td><td><strong>双工</strong></td><td><strong>全双工</strong>（TX/RX 独立）</td><td><strong>半双工</strong>（SDA 分时双向）</td><td><strong>全双工</strong>（MOSI/MISO 同时）</td></tr><tr><td>6</td><td><strong>数据方向切换</strong></td><td>不需要</td><td><strong>需要</strong>（软件实现要切 GPIO 模式）</td><td>不需要</td></tr><tr><td>7</td><td><strong>速率（本工程）</strong></td><td><strong>115200 bps</strong></td><td>软件 I2C ≈250 kHz / 硬件 I2C <strong>400 kHz</strong></td><td><strong>21 MHz</strong>（84 MHz ÷ 4）</td></tr><tr><td>8</td><td><strong>电气</strong></td><td>推挽</td><td><strong>开漏 + 上拉</strong></td><td>推挽</td></tr><tr><td>9</td><td><strong>应答机制</strong></td><td><strong>无</strong>（可加校验位/软件 ACK）</td><td><strong>每字节一个 ACK/NACK</strong></td><td><strong>无</strong></td></tr><tr><td>10</td><td><strong>每字节位数开销</strong></td><td><strong>10 位</strong>（1 起始 + 8 数据 + 1 停止）</td><td><strong>9 位</strong>（8 数据 + 1 ACK）+ 事务开销</td><td><strong>8 位</strong>（无额外开销）</td></tr><tr><td>11</td><td><strong>引脚成本 / 挂载数</strong></td><td>低（2 线）/ 只能一对</td><td><strong>最低（2 线挂一串）</strong></td><td>高（每加一个从机多一根 CS）</td></tr><tr><td>12</td><td><strong>距离</strong></td><td>较远（可到几米~几十米，加收发器更远）</td><td>近（板上，几十 cm）</td><td><strong>很短</strong>（板上，几 cm）</td></tr><tr><td>13</td><td><strong>典型用途</strong></td><td>调试口、模块间通信、GPS/蓝牙模组</td><td><strong>低速器件</strong>：RTC、EEPROM、传感器、小屏</td><td><strong>高速数据流</strong>：屏幕、Flash、SD 卡、ADC</td></tr><tr><td>14</td><td><strong>有&quot;时钟线&quot;吗</strong></td><td>无（异步，靠波特率约定）</td><td><strong>有</strong>（SCL）</td><td><strong>有</strong>（SCK）</td></tr><tr><td>15</td><td>★ <strong>能否用 SPI 去&quot;发&quot;另一种协议</strong></td><td>——</td><td>——</td><td><strong>可以</strong>：WS2812 就是&quot;用 SPI 位流拼出脉宽编码&quot;（第 30 篇）</td></tr></tbody></table><p><strong>三条&quot;最本质&quot;的差异</strong>（如果只记三条，记这三条）：</p><table tabindex="0"><thead><tr><th>本质差异</th><th>后果</th></tr></thead><tbody><tr><td><strong>① 有没有时钟线</strong></td><td>USART 异步 → 双方靠波特率对齐（<strong>速度慢且对误差敏感</strong>）；I2C/SPI 同步 → 时钟由主机给（<strong>快且可靠</strong>）</td></tr><tr><td><strong>② 有没有地址 / 片选</strong></td><td>I2C 靠地址（<strong>两线挂一串，省引脚</strong>）；SPI 靠 CS（<strong>一拖多要加引脚，但省掉了地址字节和 ACK</strong>）</td></tr><tr><td><strong>③ 电气是推挽还是开漏</strong></td><td>推挽（USART/SPI）→ 边沿陡、<strong>快</strong>；开漏+上拉（I2C）→ 能&quot;线与&quot;、<strong>能多设备共线，但慢</strong></td></tr></tbody></table><blockquote><p><strong>第 ③ 条是全篇最值得记住的因果链</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>想&quot;多设备共线&quot; → 必须&quot;线与&quot; → 必须开漏 → 必须有上拉 → 上升沿是 RC 曲线 → 速率受限</span></span>
<span class="line"><span>反过来：推挽驱动 → 边沿陡 → 可以跑 21 MHz（SPI），但一根线只能接一个从机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>&quot;为什么 I2C 慢、SPI 快&quot;的根因就在电气层，不在协议设计得差。</strong></p></blockquote><hr><h2 id="四、本工程的实际用法对照" tabindex="-1">四、本工程的实际用法对照 <a class="header-anchor" href="#四、本工程的实际用法对照" aria-label="Permalink to &quot;四、本工程的实际用法对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>USART0</strong></th><th><strong>USART2</strong></th><th><strong>I2C（<code>msp_iic</code>）</strong></th><th><strong>SPI（<code>msp_spi</code>）</strong></th></tr></thead><tbody><tr><td><strong>引脚</strong></td><td>PA9(TX) / PA10(RX)</td><td><strong>PB10(TX)</strong> / PB11(RX)</td><td>PB6(SCL) / PB7(SDA)</td><td>PA5(SCK) / PA7(MOSI) / PA6(MISO)</td></tr><tr><td><strong>总线/时钟</strong></td><td><strong>APB2 84 MHz</strong></td><td><strong>APB1 42 MHz</strong></td><td>无（软件时 GPIO / 硬件时 APB1 I2C0）</td><td><strong>APB2 84 MHz</strong></td></tr><tr><td><strong>速率</strong></td><td>115200</td><td>115200</td><td>软件 ≈250 kHz / 硬件 400 kHz</td><td><strong>21 MHz</strong>（PSC=4）</td></tr><tr><td><strong>代码位置</strong></td><td><code>Hardware/msp_uart/</code></td><td>同左（同一驱动）</td><td><code>Hardware/msp_iic/</code></td><td><code>Hardware/msp_spi/</code></td></tr><tr><td><strong>抽象层次</strong></td><td><strong>句柄化</strong>（<code>USART_HandleTypeDef</code> + D + DMA 字段）</td><td>同左</td><td><strong>宏开关双实现</strong>（软/硬）</td><td><strong>宏开关双实现</strong>（软/硬）</td></tr><tr><td><strong>上层使用</strong></td><td><code>printf</code>、<code>on_usart_recv()</code> 回调</td><td>与 STC 通信</td><td>PCF8563、OLED、触摸屏、<strong>SC12B 触摸按键</strong></td><td>SPI OLED、字库芯片、<strong>GD25Q32 Flash</strong></td></tr><tr><td><strong>有中断吗</strong></td><td>✅ RBNE + IDLE</td><td>✅ 同左</td><td><strong>总线本身无中断</strong>（轮询 + 超时）；但<strong>两个器件各有中断脚走 EXTI</strong>：PCF8563→EXTI5、SC12B→EXTI8</td><td>❌（轮询 TBE/RBNE）</td></tr><tr><td><strong>有 DMA 吗</strong></td><td>✅（<code>dma_usart</code> 分支，未合并）</td><td>✅ 同左</td><td>❌</td><td>❌</td></tr><tr><td><strong>对应笔记</strong></td><td>04 / 08</td><td>04 / 08</td><td>15 / 17 / 18 / <strong>31</strong></td><td>16 / 18 / <strong>24</strong></td></tr></tbody></table><blockquote><p><strong>SPI 那一列现在挂着四个从机</strong>（2026-10-16 之后）： <code>PA5(SCK)</code> / <code>PA7(MOSI)</code> 由 <strong>SPI-OLED（CS=PA3）</strong>、<strong>LCD（CS 另配）</strong>、<strong>GD25Q32 Flash（CS=PA4）</strong>、<strong>MAX7219 点阵屏（CS=PA8）</strong> 共用， <code>PA6(MISO)</code> 只有 Flash 用。<strong>同一时刻只能有一个 CS 有效</strong>——这就是 SPI&quot;点对点协议假装多点&quot;的代价（第 24 篇 §7.3）。</p><p><strong>★ 四个从机之后，&quot;CS 必须严格一人一根&quot;这件事更关键了</strong>： 本工程每个器件自己管自己的 CS（Flash 用 <code>bsp_flash</code> 的宏、点阵用 <code>MAX7219_CS()</code>、OLED 用 <code>PA3</code>）， <strong><code>msp_spi.c</code> 里没有任何&quot;CS 归一&quot;的假设</strong> —— 这是对的（对比 I2C 靠地址，SPI 靠片选）。</p><p><strong>I2C 那一列现在挂着四个从机</strong>（2026-10-15 之后）：<code>U5</code> OLED（0x78）、<code>U8</code> PCF8563（0x51）、<strong><code>U2</code> SC12B（0x40）</strong>、触摸屏。 <strong>同样是&quot;一条总线挂多个器件&quot;，两种协议的应对方式完全不同</strong>：</p><table tabindex="0"><thead><tr><th></th><th><strong>I2C</strong></th><th><strong>SPI</strong></th></tr></thead><tbody><tr><td>怎么区分从机</td><td><strong>设备地址</strong>（写进每一帧的第 1 个字节）</td><td><strong>片选 CS</strong>（一根独占的线）</td></tr><tr><td>加一个器件要多花</td><td><strong>0 根线</strong>（地址就够）</td><td><strong>1 根线</strong>（CS）</td></tr><tr><td>代价</td><td>每帧多 1 字节地址 + 每次都要 ACK</td><td>CS 线随器件数量线性增长</td></tr></tbody></table><p><strong>本工程&quot;4 个 I2C 从机 vs 3 个 SPI 从机&quot;，正好把这两种思路都演了一遍。</strong></p></blockquote><p><strong>注意三处&quot;工程上有意思的差异&quot;</strong>：</p><table tabindex="0"><thead><tr><th>差异</th><th>说明</th></tr></thead><tbody><tr><td><strong>同一份驱动服务两个串口（句柄化）</strong></td><td>因为串口是&quot;参数化的外设&quot;——参数不同、逻辑一样（第 04 篇的三级台阶）</td></tr><tr><td><strong>I2C/SPI 用&quot;宏开关 + 双实现&quot;</strong></td><td>因为&quot;软件实现&quot;和&quot;硬件实现&quot;逻辑完全不同，无法用参数统一；<strong>但对外接口必须一致</strong>（第 15/16 篇）</td></tr><tr><td><strong>只有串口上了 DMA 和中断</strong></td><td>因为<strong>串口是&quot;数据流&quot;型</strong>：字节源源不断、长度不定；I2C/SPI 是&quot;命令-响应&quot;型：一问一答，不值得上 DMA</td></tr></tbody></table><blockquote><p><strong>最后一行是个重要的工程判断</strong>：<strong>&quot;要不要上 DMA/中断&quot;取决于数据是不是&quot;流&quot;。</strong> 屏幕刷屏（1024 字节）虽然量大，但它是&quot;一次性写完就结束&quot;，用阻塞式发送也能接受（38 ms，每秒刷一次无所谓）；而串口接收是&quot;随时可能来、长度不定&quot;，不中断就没法处理。</p></blockquote><hr><h2 id="五、选型决策-本章最实用" tabindex="-1">五、选型决策（本章最实用） <a class="header-anchor" href="#五、选型决策-本章最实用" aria-label="Permalink to &quot;五、选型决策（本章最实用）&quot;">​</a></h2><p><strong>拿到一个新器件，按四个问题走</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1：这个器件板子上有几个同类？</span></span>
<span class="line"><span> ├─ 只有一个 / 可以每个独占一组引脚 → 走 Q2</span></span>
<span class="line"><span> └─ 需要挂一串（≥3 个，引脚紧张）  → 【I2C】（两线挂一串，靠地址区分）</span></span>
<span class="line"><span>        （典型：RTC + EEPROM + 传感器 + 小 OLED 挂在同一组 PB6/PB7 上）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q2：它的数据量大不大？</span></span>
<span class="line"><span> ├─ 大（屏幕、Flash、SD 卡、高速 ADC）→ 【SPI】（21 MHz，比 I2C 快两个数量级）</span></span>
<span class="line"><span> └─ 小（几十字节/次）                 → 看 Q3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q3：需要&quot;确认对方收到&quot;吗？</span></span>
<span class="line"><span> ├─ 需要（可写寄存器、要求可靠）→ 【I2C】（有 ACK）</span></span>
<span class="line"><span> └─ 不需要                     → 【SPI】更简单</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q4：是不是&quot;另一台设备/电脑&quot;要跟我对话？</span></span>
<span class="line"><span> └─ 是（PC、蓝牙模组、另一个单片机）→ 【USART】（异步、可远距离、加点校验就很可靠）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>再加上两条&quot;硬约束&quot;</strong>（不满足就没得选）：</p><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td><strong>器件只支持某种接口</strong></td><td>大多数器件是&quot;只有一个接口&quot;的（PCF8563 只有 I2C、W25Q Flash 只有 SPI）——<strong>选型其实是&quot;支持哪种就用哪种&quot;</strong></td></tr><tr><td><strong>引脚复用能力</strong></td><td>不是随便哪个脚都能做 I2C/SPI/USART——<strong>必须查复用表</strong>（第 14 篇的两步查法；第 20 篇的 P1 就是&quot;挪不了&quot;的真实案例）</td></tr></tbody></table><p><strong>本工程的选型痕迹</strong>（可以对照学习）：</p><table tabindex="0"><thead><tr><th>决策</th><th>结论</th><th>依据</th></tr></thead><tbody><tr><td>PCF8563（RTC）</td><td>I2C</td><td>器件只支持 I2C，且和 OLED 共用一组 PB6/PB7 → <strong>正好体现&quot;两线挂一串&quot;的优势</strong></td></tr><tr><td>两块 OLED</td><td>一块 I2C 版、一块 SPI 版</td><td><strong>学习目的</strong>：同一块屏两种接口都做一遍（第 18 篇）</td></tr><tr><td>字库芯片</td><td>SPI</td><td>挂在 SPI 总线上，和 SPI OLED 共用 SCK/MOSI/MISO，<strong>靠 CS2 区分</strong></td></tr><tr><td><strong>SC12B（触摸按键）</strong></td><td><strong>I2C</strong></td><td>器件只支持 I2C 或 BCD 直出；<strong>BCD 只能表示 1 个键，I2C 能读 12 位状态</strong> → 必须选 I2C（第 31 篇 §2.1）</td></tr><tr><td>调试输出</td><td>USART0</td><td>板载 USB-TTL 就接在 PA9/PA10，<strong>天然是调试口</strong>（硬件文档确认）</td></tr><tr><td>与 STC 通信</td><td>USART2</td><td>跨芯片通信，异步串口最简单（<strong>但 PB10 与 LCD 背光冲突</strong>，第 20 篇 P1）</td></tr><tr><td>触摸屏</td><td>I2C</td><td>器件是 I2C 触摸控制器（复用同一组 PB6/PB7）</td></tr></tbody></table><hr><h2 id="六、耗时对比-同样传-1-kb-本章数字最直观" tabindex="-1">六、耗时对比：同样传 1 KB（本章数字最直观） <a class="header-anchor" href="#六、耗时对比-同样传-1-kb-本章数字最直观" aria-label="Permalink to &quot;六、耗时对比：同样传 1 KB（本章数字最直观）&quot;">​</a></h2><p><strong>统一算&quot;传 1024 字节&quot;要多久</strong>（第 18 篇刷一次 OLED 整屏正好是 1024 字节）：</p><table tabindex="0"><thead><tr><th>协议 / 配置</th><th>有效时钟</th><th>每字节位数</th><th>用于 1 KB 的位数</th><th><strong>耗时</strong></th><th>相对 SPI</th></tr></thead><tbody><tr><td><strong>USART 115200</strong></td><td>115.2 kbps</td><td><strong>10</strong>（1 起始+8+1 停止）</td><td>10240</td><td><strong>88.9 ms</strong></td><td><strong>1/222</strong></td></tr><tr><td><strong>软件 I2C</strong>（≈250 kHz）</td><td>≈250 kHz</td><td>9 + 事务开销</td><td>≈9600</td><td><strong>≈38 ms</strong></td><td>1/95</td></tr><tr><td><strong>硬件 I2C 400 kHz</strong></td><td>400 kHz</td><td>9 + 事务开销</td><td>≈9600</td><td><strong>≈24 ms</strong></td><td>1/60</td></tr><tr><td><strong>硬件 SPI 21 MHz</strong></td><td>21 MHz</td><td><strong>8</strong></td><td>8448</td><td><strong>0.40 ms</strong></td><td><strong>1×</strong></td></tr></tbody></table><p><strong>三个可以直接背下来的数字</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 串口 115200：一个字节 ≈ 86.8 μs → 每秒最多 11520 字节</span></span>
<span class="line"><span>② I2C 400 kHz：传 1 KB ≈ 24 ms（每字节多一个 ACK 位 = 多 12.5% 时间）</span></span>
<span class="line"><span>③ SPI 21 MHz：传 1 KB ≈ 0.4 ms —— 比串口快 200 多倍</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>这三行数字能直接解释工程里的好几个决定</strong>：</p><table tabindex="0"><thead><tr><th>工程现象</th><th>用本表解释</th></tr></thead><tbody><tr><td><code>printf</code> 输出 60 字节会让看门狗喂狗节奏错位（第 12 篇）</td><td>串口最慢：60 字节 ≈ <strong>5.2 ms</strong>，而 WWDGT 窗口只有 1.66 ms</td></tr><tr><td>屏幕刷新用 I2C 要 38 ms，用 SPI 只要 0.4 ms（第 18 篇）</td><td>相差近 100 倍 → <strong>要做动画必须用 SPI</strong></td></tr><tr><td>为什么&quot;串口适合调试、不适合传数据&quot;（第 04 篇）</td><td>88.9 ms/KB → <strong>1 KB 要近 0.1 秒</strong>，数据量一大就崩</td></tr><tr><td>为什么给串口上了 DMA（第 08 篇）</td><td><strong>越慢的总线越要 DMA</strong>——因为 CPU 等不起</td></tr><tr><td><strong>触摸按键中断里读一次 I2C 就是&quot;几百微秒&quot;（第 31 篇）</strong></td><td>本表的最低档：<strong>软 I2C 每字节 ≈ 36 μs</strong>（250 kHz 下 9 个位），读 2 字节寄存器（地址帧 + 寄存器号 + 2 字节数据 ≈ 4 字节）≈ <strong>150 μs</strong> —— <strong>这个量级放在中断里，足以把主循环的 I2C 时序打断</strong></td></tr><tr><td><strong>SPI Flash 明明跑在 21 MHz，写 10 个字节却要 46 ms（第 24 篇）</strong></td><td>★ <strong>瓶颈根本不在总线</strong>：擦一个 4 KB 扇区是<strong>芯片内部的物理时间</strong>（typ 45 ms），命令只占 1.5 µs。<strong>提高 SPI 时钟对擦写速度毫无帮助</strong></td></tr></tbody></table><blockquote><p><strong>有个反直觉的推论</strong>：<strong>慢的总线更需要 DMA</strong>。 串口每字节约 87 μs，如果 CPU 阻塞着等，浪费巨大；所以第 08 篇给串口上了 DMA。 而 SPI 21 MHz 下一字节约 0.38 μs，<strong>阻塞等一会儿其实无所谓</strong>——所以本工程的 SPI 至今没上 DMA。 <strong>&quot;要不要 DMA&quot;看的是&quot;单字节耗时 × 字节数&quot;是否值得 CPU 去等。</strong></p></blockquote><h3 id="_6-1-★-第三个维度-协议之外的时间-flash-这一课" tabindex="-1">6.1 ★ 第三个维度：协议之外的时间（Flash 这一课） <a class="header-anchor" href="#_6-1-★-第三个维度-协议之外的时间-flash-这一课" aria-label="Permalink to &quot;6.1 ★ 第三个维度：协议之外的时间（Flash 这一课）&quot;">​</a></h3><p>Flash 是本工程<strong>第一个&quot;通信极快、任务极慢&quot;的器件</strong>，它把&quot;耗时&quot;这件事拆成了两层：</p><table tabindex="0"><thead><tr><th>层次</th><th>时间</th><th>谁决定</th><th>提高时钟有用吗</th></tr></thead><tbody><tr><td><strong>通信时间</strong></td><td>1 KB ≈ 0.4 ms（21 MHz）</td><td>总线时钟</td><td>✅ 有用</td></tr><tr><td><strong>器件内部时间</strong></td><td>擦 4 KB 扇区 ≈ <strong>45 ms</strong>；写 1 页 256 B ≈ <strong>0.7 ms</strong></td><td><strong>器件物理（高压擦写）</strong></td><td>❌ <strong>完全无用</strong></td></tr></tbody></table><p><strong>推论（对&quot;选协议&quot;的直接影响）</strong>：</p><ol><li><strong>选 SPI 而不用 I2C/串口的理由，对 Flash 依然成立</strong>（读数据、发命令快）；</li><li><strong>但&quot;写操作快不快&quot;跟协议毫无关系</strong>——所以&quot;用 Quad-SPI / 更快时钟&quot;只在<strong>读</strong>的场合有意义；</li><li><strong>真正决定 Flash 用法的是&quot;擦除次数&quot;</strong>：能凑满一整个扇区再写，就绝不写第二次（第 24 篇第七章）。</li><li><strong>它引入了第二种&quot;必须等&quot;</strong>：第 13 篇把时间分成&quot;硬件时间/软件时间&quot;，这里补上第三类——<strong>物理时间</strong>（第 13 篇 §7.4）。</li></ol><blockquote><p><strong>一句话总括这个专题</strong>：<strong>协议决定&quot;每字节多快&quot;，器件决定&quot;每个操作多慢&quot;。</strong> 前者可以靠换协议优化，后者只能靠&quot;少做几次&quot;来优化。</p></blockquote><hr><h2 id="七、电气差异-为什么-i2c-慢、spi-快-因果链" tabindex="-1">七、电气差异：为什么 I2C 慢、SPI 快（因果链） <a class="header-anchor" href="#七、电气差异-为什么-i2c-慢、spi-快-因果链" aria-label="Permalink to &quot;七、电气差异：为什么 I2C 慢、SPI 快（因果链）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【I2C】必须&quot;多设备共线&quot;</span></span>
<span class="line"><span>     ↓ 那就必须&quot;线与&quot;（任何一个设备都能拉低，谁也不能强推高）</span></span>
<span class="line"><span>     ↓ 那就必须&quot;开漏输出 + 上拉电阻&quot;</span></span>
<span class="line"><span>     ↓ 那上升沿就是&quot;上拉电阻 × 总线电容&quot;的 RC 充电曲线</span></span>
<span class="line"><span>     ↓ 电阻不能太小（省电 &amp; 驱动能力），电容不能太小（线长/挂载数决定）</span></span>
<span class="line"><span>     ⇒ 上升时间被限制在百 ns ~ μs 级 ⇒ 速率上限 ≈ 100 k ~ 400 k（快速模式 1 MHz 也吃力）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【SPI】点对点，不需要共线</span></span>
<span class="line"><span>     ↓ 可以&quot;推挽输出&quot;（主动拉高、主动拉低）</span></span>
<span class="line"><span>     ↓ 边沿由晶体管驱动，陡得多</span></span>
<span class="line"><span>     ⇒ 可以跑到几十 MHz（本工程 21 MHz）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>对照表</strong>：</p><table tabindex="0"><thead><tr><th></th><th>I2C（开漏 + 上拉）</th><th>SPI / USART（推挽）</th></tr></thead><tbody><tr><td>谁决定上升沿</td><td><strong>上拉电阻 + 总线电容（RC 充电）</strong></td><td>晶体管驱动（几十 ns）</td></tr><tr><td>能多设备共线吗</td><td>✅（线与）</td><td>❌（会短路，见第 10/15 篇）</td></tr><tr><td>速率上限</td><td>≈几百 kHz ~ 1 MHz</td><td><strong>几十 MHz</strong></td></tr><tr><td>省电吗</td><td>低电平时有持续灌电流</td><td>静态几乎不耗</td></tr><tr><td>引脚需要复用的能力</td><td>普通开漏 GPIO 也行（<strong>可以软件模拟</strong>）</td><td>需要硬件外设 + AF 复用（<strong>软件模拟会慢很多</strong>）</td></tr></tbody></table><p><strong>最后一行解释了一个工程现象</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I2C 用&quot;软件模拟&quot;很常见（本工程默认就是软件 I2C）——因为开漏 GPIO 就能做，速度也不快，软件能跟上。</span></span>
<span class="line"><span>SPI 用&quot;软件模拟&quot;就吃亏了——推挽 GPIO 翻转速度受 CPU 限制（几百 kHz ~ 几 MHz），</span></span>
<span class="line"><span>                              和硬件的 21 MHz 差几十倍。</span></span>
<span class="line"><span>⇒ 本工程 SPI 软/硬实现的性能差距，比 I2C 的软/硬差距大得多（第 16 篇的练习题 5 就是要测这个）。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="八、本工程还没碰的通信协议-未来的方向" tabindex="-1">八、本工程还没碰的通信协议（未来的方向） <a class="header-anchor" href="#八、本工程还没碰的通信协议-未来的方向" aria-label="Permalink to &quot;八、本工程还没碰的通信协议（未来的方向）&quot;">​</a></h2><p><strong>板上硬件已经具备、但代码还没写的</strong>（来自第 20 篇的硬件文档）：</p><table tabindex="0"><thead><tr><th>协议</th><th>板上的硬件</th><th>引脚</th><th>什么时候会需要</th></tr></thead><tbody><tr><td><strong>CAN</strong></td><td><code>TJA1050</code> 收发器 + <code>H7</code> 总线端子</td><td><strong>PB13=TX / PB12=RX</strong></td><td><strong>汽车电子/工业现场</strong>：多节点、抗干扰、带仲裁和重传，比串口可靠得多</td></tr><tr><td><strong>单总线 1-Wire</strong></td><td><code>DHT11</code> 温湿度</td><td>PB15</td><td>单器件、单根线、<strong>靠严格时序通信</strong>（是&quot;软件时序&quot;的极端案例）</td></tr><tr><td><strong>USB</strong></td><td>芯片内置 USBFS/USBHS</td><td>—</td><td>需要和 PC 高速通信</td></tr><tr><td><strong>以太网</strong></td><td>芯片内置 ENET</td><td>—</td><td>联网设备</td></tr><tr><td><strong>I2C 触摸屏</strong></td><td>触摸控制器（复用 PB6/PB7）</td><td>+ PD7=RST / PB4=INT</td><td>做带触摸的界面</td></tr><tr><td><strong>FSMC/LCD 并口</strong></td><td>LCD（FPC 接口）</td><td>PD6/PA5/PA7/PB0/PB1/PB10</td><td>大屏、高刷新率（<strong>并口比 SPI 快得多</strong>）</td></tr></tbody></table><p><strong>四种协议的定位对比</strong>（补上 CAN 和 1-Wire 会更完整）：</p><table tabindex="0"><thead><tr><th>协议</th><th>线数</th><th>拓扑</th><th>速率</th><th>核心特点</th><th>典型场景</th></tr></thead><tbody><tr><td>USART</td><td>2</td><td>点对点</td><td>中（115 k~几 Mbps）</td><td>简单、异步、无地址</td><td>调试、模组通信</td></tr><tr><td>I2C</td><td>2</td><td><strong>多设备总线</strong></td><td>低（100 k~1 M）</td><td><strong>有地址、有应答</strong></td><td>低速器件群</td></tr><tr><td>SPI</td><td>4+CS</td><td>点对点</td><td><strong>高（几十 M）</strong></td><td>快、简单、<strong>无应答</strong></td><td>数据流（屏/Flash）</td></tr><tr><td><strong>CAN</strong></td><td><strong>2</strong>（差分）</td><td><strong>多主总线</strong></td><td>中（最高 1 Mbps）</td><td><strong>差分抗干扰、硬件仲裁与重传、错误检测</strong></td><td>汽车、工业</td></tr><tr><td><strong>1-Wire</strong></td><td><strong>1</strong></td><td>多设备</td><td>低</td><td><strong>一根线供电+通信、严格时序</strong></td><td>单颗温度传感器</td></tr></tbody></table><blockquote><p><strong>CAN 的独特之处</strong>（值得单独记住）：<strong>它是本表里唯一&quot;硬件负责可靠性&quot;的协议</strong>——自动重传、自动仲裁（谁先说话由硬件决定）、CRC 校验、错误帧。<strong>I2C 的 ACK 只确认&quot;收到了&quot;，SPI 和 UART 干脆什么都不保证。</strong> 所以&quot;要多节点 + 要可靠&quot;的场合，CAN 是正解；<strong>本工程的几个串口通信场景都还没有可靠性要求，所以用 UART 就够了。</strong></p></blockquote><hr><h2 id="九、自测题" tabindex="-1">九、自测题 <a class="header-anchor" href="#九、自测题" aria-label="Permalink to &quot;九、自测题&quot;">​</a></h2><ol><li>用&quot;线数 / 拓扑 / 寻址 / 同步 / 双工 / 速率 / 电气 / 应答&quot;八个词说出 USART、I2C、SPI 的差别。</li><li>为什么三个驱动的 API 形态完全不同（<code>write_nbyte(addr,reg,...)</code> / <code>write_byte(dat,cmd)</code> / <code>send_string(str)</code>）？这和各协议的&quot;应用层语义&quot;有什么关系？</li><li>&quot;I2C 慢、SPI 快&quot;的<strong>根因</strong>在哪一层？请把因果链完整说一遍。</li><li>I2C 为什么必须开漏？开漏带来了什么好处、什么代价？</li><li>同样传 1 KB：USART 115200、I2C 400 kHz、SPI 21 MHz 各要多久？各举一个&quot;这个数字解释了某个工程现象&quot;的例子。</li><li>为什么&quot;越慢的总线越需要 DMA&quot;？为什么本工程的 SPI 至今没上 DMA？</li><li>I2C 每字节比 SPI 多 1 位（ACK）——这在传 1 KB 时多花多少时间？</li><li>本工程哪两个器件挂在同一组 I2C 线上？这体现了 I2C 的什么优势？</li><li>本工程 SPI 上挂了屏幕和字库芯片两颗——为什么需要两个 CS？如果只用一根 CS 会怎样？</li><li>如果一个新器件&quot;支持 I2C 也支持 SPI&quot;，你会怎么选？（给出判断步骤）</li><li>USART、SPI 都&quot;没有应答&quot;，它们各自靠什么保证可靠？（举本工程的做法）</li><li>CAN 和 I2C 都说&quot;多设备总线&quot;，它们的可靠性机制有什么区别？</li></ol><h2 id="十、练习题" tabindex="-1">十、练习题 <a class="header-anchor" href="#十、练习题" aria-label="Permalink to &quot;十、练习题&quot;">​</a></h2><ol><li><strong>做一次实测对比</strong>：用逻辑分析仪分别抓 UART 发 10 字节、I2C 发 10 字节、SPI 发 10 字节的波形，量出实际耗时，和第六章的理论值对比。</li><li><strong>算一遍误差</strong>：串口 115200 在 APB2（84 MHz）和 APB1（42 MHz）下的实际波特率误差各是多少（第 13 篇 5.9 节有算法），并解释为什么两端误差要&quot;总共小于一定值&quot;。</li><li><strong>换总线实验</strong>：把 PCF8563（I2C）换成挂在 SPI 上（假设有 SPI 版本的 RTC 芯片），写出需要改的代码清单，体会&quot;换总线要改哪几层&quot;。</li><li><strong>加一根 CS</strong>：在 SPI 总线上再挂一颗 SPI Flash（W25Q），画一张&quot;SPI 总线接线图&quot;，标清 SCK/MOSI/MISO 共用、CS 各自独立。</li><li><strong>补 CAN</strong>：按硬件文档的引脚（PB13/PB12 + TJA1050），把 CAN 收发跑通，并和第 04 篇的串口做一次&quot;抗干扰/可靠性&quot;的对比实验（例如故意干扰总线，看谁的误码率低）。</li><li><strong>补单总线</strong>：驱动 DHT11（PB15），体会 1-Wire 的&quot;严格时序&quot;——它没有时钟线也没地址，<strong>全靠微秒级延时</strong>（对比一下：这和软件 I2C 的延时要求有什么异同）。</li><li><strong>写一张自己的对比表</strong>：把你手头项目的所有通信器件列出来，按本专题的十一维度填一遍，找出&quot;有没有选错总线&quot;的地方。</li></ol><hr><h2 id="十一、附-本专题引用的提交" tabindex="-1">十一、附：本专题引用的提交 <a class="header-anchor" href="#十一、附-本专题引用的提交" aria-label="Permalink to &quot;十一、附：本专题引用的提交&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>相关提交</th><th>对应笔记</th></tr></thead><tbody><tr><td><strong>USART</strong></td><td><code>31f8243</code>、<code>d41b189</code>、<code>ebc8568</code>、<code>8e13d14</code>、<code>56609c3</code>、<code>6a37639</code>、<code>d251346</code></td><td>04</td></tr><tr><td><strong>USART + DMA</strong></td><td><code>57be122</code>、<code>af0741c</code>、<code>90e109f</code>（<code>dma_usart</code> 分支）</td><td>08</td></tr><tr><td><strong>I2C（软/硬）</strong></td><td><code>7711e72</code>、<code>ae57848</code>、<code>d3a0319</code>、<code>c2dc4c2</code>、<code>5ce9c77</code>、<code>886ba18</code></td><td>15</td></tr><tr><td><strong>SPI（软/硬）</strong></td><td><code>5ce9c77</code>、<code>b32b17a</code>、<code>5334620</code>、<code>18cec36</code>（补全双工接口）</td><td>16</td></tr><tr><td><strong>SPI 器件：GD25Q32 Flash（★ 唯一&quot;通信快、任务慢&quot;的例子）</strong></td><td><code>915f21f</code>、<code>18cec36</code></td><td><strong>24</strong></td></tr><tr><td><strong>I2C 器件：PCF8563</strong></td><td><code>ccb3c81</code>、<code>d3a0319</code>、<code>886ba18</code>、<code>57b3f4a</code>、<code>7ad0213</code>、<code>87da7e0</code>（修重入）</td><td>17</td></tr><tr><td><strong>I2C/SPI 器件：OLED</strong></td><td><code>e941ecb</code>、<code>886ba18</code>、<code>13cf2f3</code>、<code>5ce9c77</code>、<code>b32b17a</code>、<code>5334620</code></td><td>18</td></tr><tr><td><strong>I2C 器件：SC12B 触摸按键</strong></td><td><code>2bdc21f</code>、<code>dcdda0d</code>（<strong>修 IIC 重入</strong>，与 <code>87da7e0</code> 同类）</td><td><strong>31</strong></td></tr><tr><td>硬件侧（未实现的 CAN/1-Wire 等）</td><td><code>e2d7adf</code></td><td>20</td></tr></tbody></table><h2 id="参考笔记" tabindex="-1">参考笔记 <a class="header-anchor" href="#参考笔记" aria-label="Permalink to &quot;参考笔记&quot;">​</a></h2><ul><li><code>../../../NOTE/Note/UART.md</code> —— UART/USART 串口通信（串行 vs 并行、帧格式、校验方式、引脚复用表）</li><li><code>../../../NOTE/Note/IIC.md</code> —— IIC 总线（开漏电气、四条时序规则、软硬实现、两个实战）</li><li><code>../../../NOTE/Note/SPI.md</code> —— SPI 总线（CPOL/CPHA、存储器分类、软硬实现、Flash 与屏幕实战）</li><li><code>../../../NOTE/Textbook/UART/</code>、<code>../../../NOTE/Textbook/IIC/</code>、<code>../../../NOTE/Textbook/SPI/</code> —— 三套教材原文快照</li><li><a href="./13-专题-计时外设与频率计算.html">13 篇</a> 5.9 节 —— 串口波特率的分频与误码率</li><li><a href="./14-专题-时钟树与总线.html">14 篇</a> 第五章 —— 三个外设分别挂在哪条总线（&quot;总线&quot;这个词在代码里的含义）</li><li><a href="./21-专题-定时器扩展功能汇总与比较.html">21 篇</a> —— 姊妹篇（那篇讲&quot;定时器系&quot;，这篇讲&quot;通信系&quot;）</li></ul><blockquote><p>本笔记仅作学习整理，内容来自本仓库真实提交记录与源码。</p></blockquote>`,80)])])}const h=s(r,[["render",a]]);export{u as __pageData,h as default};
